function sqlStringLiteral(value) {
    return "'" + String(value).replace(/'/g, "''") + "'";
}

function readPayloadObject(payload) {
    if (payload && typeof payload === "object" && !Buffer.isBuffer(payload)) {
        return payload;
    }

    if (Buffer.isBuffer(payload)) {
        payload = payload.toString("utf8");
    }

    if (typeof payload === "string") {
        const trimmed = payload.trim();
        if (!trimmed) {
            return {};
        }
        try {
            const parsed = JSON.parse(trimmed);
            return parsed && typeof parsed === "object" ? parsed : {};
        } catch (error) {
            return {};
        }
    }

    return {};
}

const payload = readPayloadObject(msg.payload);
const deviceId = typeof payload.device_id === "string" ? payload.device_id.trim() : "";
const rawName = typeof payload.display_name === "string"
    ? payload.display_name
    : typeof payload.device_name === "string"
        ? payload.device_name
        : "";
const normalizedName = rawName.trim();

if (!deviceId) {
    msg.statusCode = 400;
    msg.payload = {
        error: "device_id_required",
        message: "device_id is required"
    };
    return [null, msg];
}

if (normalizedName.length > 80) {
    msg.statusCode = 400;
    msg.payload = {
        error: "display_name_too_long",
        message: "display_name must be 80 characters or fewer"
    };
    return [null, msg];
}

const updatedAt = new Date().toISOString();
const nameSql = normalizedName ? sqlStringLiteral(normalizedName) : "NULL";
msg.dashboardDisplayNameUpdate = {
    device_id: deviceId,
    display_name: normalizedName || null,
    updated_at: updatedAt
};
msg.topic = "UPDATE devices SET dashboard_display_name = " + nameSql + ", updated_at = " + sqlStringLiteral(updatedAt) + " WHERE device_id = " + sqlStringLiteral(deviceId) + " RETURNING device_id, dashboard_display_name, updated_at;";
return [msg, null];

const update = msg.dashboardDisplayNameUpdate || {};
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const row = rows.length > 0 ? rows[0] : null;

if (!row) {
    msg.statusCode = 404;
    msg.payload = {
        error: "device_not_found",
        message: "device not found",
        device_id: update.device_id || null
    };
    return msg;
}

msg.statusCode = 200;
msg.payload = {
    device_id: row.device_id || update.device_id || null,
    display_name: row.dashboard_display_name || null,
    updated_at: row.updated_at || update.updated_at || new Date().toISOString()
};
return msg;
